  "codebook": {
    "definition": "Credit-claiming occurs when a senator explicitly attributes a positive outcome, action, or achievement to their own efforts, leadership, or influence, either directly or through their office.",
    "clarification": "Credit-claiming is identified when the senator uses first-person language (e.g., 'I,' 'my,' 'we') or explicitly states their role in securing, introducing, or achieving a specific result. This includes announcing funding, legislation, or other tangible benefits that they directly facilitated. The focus is on the senator taking personal or office-based responsibility for a positive development.",
    "positive_examples": [
      {
        "document_id": "89",
        "explanation": "Senator Dorgan explicitly states, 'Dorgan authored legislation, which was signed into law, that created the National Center designation,' directly attributing the outcome to his own legislative efforts."
      },
      {
        "document_id": "2318",
        "explanation": "Senator Durbin states, 'I helped secure an expedited environmental review from the federal government and facilitated the return of the project to the national priority list for federal funding,' clearly claiming personal credit for the actions taken."
      },
      {
        "document_id": "3482",
        "explanation": "Senators Mikulski and Cardin announce federal funding for firefighters and explicitly tie it to their efforts, with Senator Mikulski stating, 'I will continue to fight to provide the federal support they need,' and the funding being a result of their advocacy."
      }
    ],
    "negative_clarification": "Credit-claiming does NOT occur when a senator discusses general policy positions, criticizes others, or provides information without explicitly linking it to their own actions or influence. Statements that are purely informative, critical, or expressive of support without personal attribution do not qualify as credit-claiming.",
    "negative_examples": [
      {
        "document_id": "50",
        "explanation": "Senator Reid criticizes the Administration's position on global warming but does not claim any personal credit for actions or outcomes. The statement is purely critical and does not attribute any positive result to his own efforts."
      },
